    let name_bytes = filename.as_bytes();
    name_bytes.len() == 1 && name_bytes[0] == DOT_BYTE
}

/// Checks if the file name is "..", indicating it's the parent directory.
pub const fn is_dotdot(filename: &str) -> bool {
    file_ctx: XattrFileCtx,
    name_ptr: Vaddr,
    user_space: &CurrentUserSpace,
    ctx: &Context,
) -> Result<()> {
    let name_cstr = read_xattr_name_cstr_from_user(name_ptr, user_space)?;
    let name_str = name_cstr.to_string_lossy();
    let xattr_name = parse_xattr_name(name_str.as_ref())?;
    check_xattr_write_permission(&xattr_name, ctx)?;

    match lookup_path_for_xattr(&file_ctx, ctx) {
        Ok(path) => {
            path.remove_xattr(xattr_name)?;
            fs::vfs::notify::on_attr_change(&path);
            Ok(())
        }
        Err(e) => Err(e),
    }
}

